import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    response = requests.get(url, params=parameters, headers=HEADERS)
    if not response.ok:
        raise Exception("URL cannot be accessed or invalid")

    try:
        data = response.json()
    except json.JSONDecodeError:
        raise Exception("Invalid data")

    if not data:
        raise Exception("Empty data")

    if isinstance(data, list):
        df = pd.DataFrame(data)
    elif isinstance(data, dict) and 'data' in data:
        df = pd.DataFrame(data['data'])
    else:
        raise Exception("Invalid data structure")

    if df.empty:
        raise Exception("Empty data")

    numeric_df = df.select_dtypes(include=['number'])

    if numeric_df.empty:
        raise Exception("No numerical characteristics found")

    corr_matrix = numeric_df.corr()

    ax = sns.heatmap(corr_matrix, annot=True, cmap='coolwarm')

    return df, ax

